import{_ as o,C as c,o as a,c as r,a5 as e,E as n}from"./chunks/framework.-jms6n7v.js";const g=JSON.parse('{"title":"타입","description":"API가 받고 돌려주는 타입을 사이드바에서 고른 언어 기준으로 하나씩 따로 정리했습니다.","frontmatter":{"title":"타입","order":1,"pageClass":"reference-page","prev":{"text":"API","link":"/ko/api/"},"next":{"text":"다른 DB와 비교","link":"/ko/compare"}},"headers":[{"level":2,"title":"언어별 필드 타입","slug":"언어별-필드-타입","link":"#언어별-필드-타입","children":[]}],"relativePath":"ko/types/index.md","filePath":"ko/types/index.md","lastUpdated":1791607547000}'),i={name:"ko/types/index.md"};function l(p,d,s,h,b,_){const t=c("PageList");return a(),r("div",null,[d[0]||(d[0]=e('<h1 id="타입" tabindex="-1">타입 <a class="header-anchor" href="#타입" aria-label="Permalink to &quot;타입&quot;">​</a></h1><p>API가 받고 돌려주는 타입을 사이드바에서 고른 언어 기준으로 하나씩 따로 정리했습니다.</p><div class="lang-only" data-code-lang="rust"><p>모든 타입은 크레이트 최상위에서 <code>darudb::Value</code>처럼 가져옵니다. 이 타입을 받고 돌려주는 호출은 <a href="./../api/">API</a>에 있습니다.</p></div><div class="lang-only" data-code-lang="node"><p>TypeScript용 타입은 패키지 최상위에서 <code>import type { OpenOptions } from &#39;darudb&#39;;</code>처럼 가져옵니다. 이 타입을 받고 돌려주는 호출은 <a href="./../api/">API</a>에 있습니다.</p></div><div class="lang-only" data-code-lang="dart"><p>타입은 패키지의 라이브러리 <code>package:darudb/darudb.dart</code>에서 내보냅니다. 이 타입을 받고 돌려주는 호출은 <a href="./../api/">API</a>에 있습니다.</p></div><div class="lang-only" data-code-lang="python"><p>타입은 패키지 최상위에서 <code>darudb.Key</code>처럼 쓰거나 <code>from darudb import CheckReport</code>처럼 가져옵니다. 패키지에 타입 힌트가 함께 들어 있습니다. 이 타입을 받고 돌려주는 호출은 <a href="./../api/">API</a>에 있습니다.</p></div>',6)),n(t,{section:"types",grouped:""}),d[1]||(d[1]=e('<h2 id="언어별-필드-타입" tabindex="-1">언어별 필드 타입 <a class="header-anchor" href="#언어별-필드-타입" aria-label="Permalink to &quot;언어별 필드 타입&quot;">​</a></h2><p>스키마의 필드에는 아래 가운데 하나가 담깁니다. 패키지마다 선언하는 방법과 읽어 오는 타입은 다르지만, 한 언어에서 쓴 파일을 다른 언어에서 읽어도 똑같이 읽힙니다.</p><table tabindex="0"><thead><tr><th>필드에 담기는 것</th><th>Rust</th><th>Node.js</th><th>Dart</th><th>Python</th></tr></thead><tbody><tr><td>불리언</td><td><code>Type::Bool</code>, <code>bool</code></td><td><code>t.bool()</code>, <code>boolean</code></td><td><code>bool</code></td><td><code>bool</code></td></tr><tr><td>64비트 정수</td><td><code>Type::Int</code>, <code>i64</code></td><td><code>t.int()</code>, <code>number</code>, 또는 <code>t.bigint()</code>, <code>bigint</code></td><td><code>int</code></td><td><code>int</code></td></tr><tr><td>64비트 실수</td><td><code>Type::Float</code>, <code>f64</code></td><td><code>t.float()</code>, <code>number</code></td><td><code>double</code></td><td><code>float</code></td></tr><tr><td>문자열</td><td><code>Type::String</code>, <code>String</code></td><td><code>t.string()</code>, <code>string</code></td><td><code>String</code></td><td><code>str</code></td></tr><tr><td>바이트</td><td><code>Type::Bytes</code>, <code>Vec&lt;u8&gt;</code></td><td><code>t.bytes()</code>, <code>Uint8Array</code></td><td><code>Uint8List</code></td><td><code>bytes</code></td></tr><tr><td>목록</td><td><code>Type::list(...)</code>, <code>Vec&lt;T&gt;</code></td><td><code>t.list(...)</code>, 배열</td><td><code>List&lt;E&gt;</code></td><td><code>list[E]</code></td></tr><tr><td>다른 컬렉션으로 가는 링크</td><td><code>Type::link(...)</code>, <code>Link&lt;T&gt;</code></td><td><code>t.link(...)</code>, 키</td><td><code>Link&lt;T&gt;</code></td><td>키 타입과 <code>field(link=...)</code></td></tr><tr><td>내장 객체</td><td><code>Type::object(...)</code>, <code>#[derive(Embedded)]</code>를 붙인 구조체</td><td><code>t.object({...})</code>, 객체</td><td><code>@Embedded()</code>를 붙인 클래스</td><td><code>@darudb.embedded</code>를 붙인 클래스</td></tr><tr><td>선택 필드의 빈 값</td><td><code>optional(...)</code>, <code>Option&lt;T&gt;</code></td><td><code>.optional()</code>, <code>null</code></td><td>널 허용 타입, <code>null</code></td><td><code>X | None</code>, <code>None</code></td></tr></tbody></table><p>Rust에서 짝의 앞쪽은 <a href="./../api/rust/schema"><code>Schema</code></a>에서 필드를 선언하는 방법이고, 뒤쪽은 <a href="./../api/rust/derive"><code>#[derive(Object)]</code></a>로 컬렉션으로 만든 구조체에서 쓰는 타입입니다. Node.js에서 앞쪽은 <a href="./../api/node/t"><code>t</code></a> 빌더이고, 뒤쪽은 객체에 담기는 값입니다. Dart와 Python은 클래스에 적은 타입으로 필드를 선언합니다. 자세한 내용은 언어별 필드 타입 페이지에 있습니다.</p>',4))])}const y=o(i,[["render",l]]);export{g as __pageData,y as default};
